/**
 * The measurement, written down.
 *
 * Every number here was produced by `runs.ts` — fourteen Vitest processes
 * against copies of `fixture/` — and `runs.test.ts` produces them again on
 * every `pnpm test` and fails if any cell has moved. Nothing in this file is
 * computed from the selector it is scoring, which is the only reason it is
 * worth reading: a table generated by the thing it describes agrees with it by
 * construction.
 *
 * `README.md` renders these numbers and `readme.test.ts` checks that it renders
 * *these* numbers, so the document cannot drift from the table and the table
 * cannot drift from the runs.
 */

import { FAULT_IDS, type FaultId } from './faults.ts'
import type { StrategyId } from './strategies.ts'

/** What actually broke: the ground truth, per fault, measured and not derived. */
export const GROUND_TRUTH: Readonly<Record<FaultId, readonly string[]>> = {
  'bulk-threshold': ['src/cart.test.ts', 'src/pricing.test.ts'],
  'scale-cents': ['src/cart.test.ts', 'src/money.test.ts', 'src/pricing.test.ts'],
  'test-factory': ['src/cart.test.ts', 'src/label.test.ts', 'src/pricing.test.ts'],
  'runtime-rule': ['src/rules/registry.test.ts'],
  'rate-table': ['src/rates.test.ts'],
  'snapshot-baseline': ['src/label.test.ts'],
  // Five of six. `label.test.ts` is the one suite that never calls the matcher
  // the fault rewrites — a reminder that "a setup change breaks everything" is
  // a measurement too, and this one came back 5/6.
  'setup-matcher': [
    'src/cart.test.ts',
    'src/money.test.ts',
    'src/pricing.test.ts',
    'src/rates.test.ts',
    'src/rules/registry.test.ts',
  ],
  'new-test': ['src/discount.test.ts'],
}

/** Suites in the subject as each fault leaves it. `new-test` adds one. */
export const SUITES: Readonly<Record<FaultId, number>> = {
  'bulk-threshold': 6,
  'scale-cents': 6,
  'test-factory': 6,
  'runtime-rule': 6,
  'rate-table': 6,
  'snapshot-baseline': 6,
  'setup-matcher': 6,
  'new-test': 7,
}

/** One cell: how many suites the strategy selected, and whether that covered every failure. */
export interface Cell {
  readonly selected: number
  readonly safe: boolean
}

const cells = (
  counts: readonly [number, number, number, number, number, number, number, number],
  unsafe: readonly FaultId[],
): Readonly<Record<FaultId, Cell>> => {
  const missing = new Set(unsafe)

  return Object.fromEntries(
    FAULT_IDS.map((fault, index) => [fault, { selected: counts[index] ?? 0, safe: !missing.has(fault) }]),
  ) as Readonly<Record<FaultId, Cell>>
}

/**
 * The matrix: eight strategies against eight faults.
 *
 * The counts are in the order of `FAULT_IDS`: bulk-threshold, scale-cents,
 * test-factory, runtime-rule, rate-table, snapshot-baseline, setup-matcher,
 * new-test. The second argument lists the faults the strategy was *unsafe* on
 * — it missed a suite that failed — which is the only column that can
 * disqualify a row.
 */
export const MATRIX: Readonly<Record<StrategyId, Readonly<Record<FaultId, Cell>>>> = {
  all: cells([6, 6, 6, 6, 6, 6, 6, 7], []),
  'changed-tests': cells(
    [0, 0, 0, 0, 0, 0, 0, 1],
    ['bulk-threshold', 'scale-cents', 'test-factory', 'runtime-rule', 'rate-table', 'snapshot-baseline', 'setup-matcher'],
  ),
  'same-directory': cells(
    [5, 5, 0, 1, 0, 0, 0, 6],
    ['test-factory', 'rate-table', 'snapshot-baseline', 'setup-matcher'],
  ),
  'importers-direct': cells(
    [1, 1, 4, 0, 0, 0, 0, 1],
    ['bulk-threshold', 'scale-cents', 'runtime-rule', 'rate-table', 'snapshot-baseline', 'setup-matcher'],
  ),
  'importers-transitive': cells(
    [2, 5, 4, 0, 0, 0, 0, 1],
    ['runtime-rule', 'rate-table', 'snapshot-baseline', 'setup-matcher'],
  ),
  'transitive-triggers': cells(
    [2, 5, 4, 0, 0, 0, 6, 1],
    ['runtime-rule', 'rate-table', 'snapshot-baseline'],
  ),
  'transitive-triggers-edges': cells([2, 5, 4, 1, 1, 1, 6, 1], []),
  coverage: cells([2, 4, 4, 1, 0, 0, 0, 0], ['rate-table', 'snapshot-baseline', 'setup-matcher', 'new-test']),
}

/** Total suites a strategy selects across the whole catalogue, out of 49. */
export function totalSelected(strategy: StrategyId): number {
  return FAULT_IDS.reduce((sum, fault) => sum + (MATRIX[strategy][fault]?.selected ?? 0), 0)
}

/** Suites in the catalogue, summed: the denominator every row is measured against. */
export const TOTAL_SUITES = FAULT_IDS.reduce((sum, fault) => sum + SUITES[fault], 0)

/** The faults a strategy misses at least one failing suite on. */
export function unsafeFaults(strategy: StrategyId): readonly FaultId[] {
  return FAULT_IDS.filter((fault) => !MATRIX[strategy][fault]?.safe)
}
